// Settings for the assessment step. Change the model here; nothing else needs to change.
// Prices are per million tokens, used only to log the cost of each call in model_calls.
return [{ json: {
  model: 'claude-haiku-5-5',      // the smallest current model; a reading task like this one doesn't need more
  effort: 'low',                 // extraction is a reading task; low effort keeps cost down
  price_in_per_mtok: 0.10,
  price_out_per_mtok: 0.50,
  // Change this date whenever the extraction or fit rules change: every open tender is then assessed again on the next run.
  rules_version: '2026-11-05c',
  // Approximate euro value of one unit, to compare minimums stated in Scandinavian currencies. Update now and then.
  eur_per: { EUR: 1, DKK: 0.134, SEK: 0.09, NOK: 0.085 },
  max_tenders_per_run: 300,      // safety cap (about $0.40 with Haiku); the rest wait for the next run
} }];

// Get the requirement text of each tender from TED (plain code, no model) and build one model request per tender.
// TED's Search API is free and needs no key. Notices are asked for 100 at a time, with a short pause between requests.
const s = $('Settings').first().json;
const { tenders, refs, facts, run_id } = $input.first().json;
if (!tenders.length) return [];                                  // nothing new to assess
if (!refs.length) throw new Error('No reference projects in the database. Run db/seed.sql once, then run this again.');

const FIELDS = ['publication-number', 'procedure-type', 'title-lot', 'description-proc', 'description-lot',
  'selection-criterion-lot', 'selection-criterion-name-lot', 'selection-criterion-description-lot',
  'award-criterion-type-lot', 'award-criterion-name-lot', 'award-criterion-description-lot', 'award-criterion-number-weight-lot',
  'estimated-value-proc', 'estimated-value-cur-proc'];

const found = [];
for (let i = 0; i < tenders.length; i += 100) {
  if (i) await new Promise(r => setTimeout(r, 500));
  const ids = tenders.slice(i, i + 100).map(t => t.source_id);
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.ted.europa.eu/v3/notices/search',
    body: { query: `publication-number IN (${ids.join(' ')})`, fields: FIELDS, limit: 100, page: 1 },
    json: true,
  });
  found.push(...(res.notices || []));
}
const byId = Object.fromEntries(found.map(n => [n['publication-number'], n]));

// TED gives text per language ({deu: [...]}) or plain lists. Keep every value, in the notice's own language.
const texts = v => {
  if (v == null) return [];
  if (Array.isArray(v)) return v.flatMap(texts);
  if (typeof v === 'object') return Object.values(v).flatMap(texts);
  return [String(v)];
};
const section = (label, v) => { const t = [...new Set(texts(v))].join('\n'); return t ? `## ${label}\n${t}` : ''; };

const SYSTEM = `You read one public tender notice for architecture or landscape services and extract its stated requirements into the given JSON schema.
Rules:
- Use only what the notice text says. If a requirement is not stated, set it to null. Never guess or fill in typical values.
- Every value you give must have a quote: copy the exact words from the notice, in the notice's own language, short (under 30 words). The quote must appear in the text character for character.
- Give amounts as stated, with their currency (EUR, DKK, SEK, NOK, or other). Do not convert.
- Fill a minimum only when the notice states a number. If it only asks bidders to declare their turnover, insurance or staff, leave the value null.
- "references": the minimum number of comparable projects the bidder must show, and what counts as comparable.
- Insurance: put the highest stated cover amount of any liability insurance (professional, personal injury or property damage) in min_professional_indemnity_eur.
- Turnover: put the stated minimum annual turnover in min_annual_turnover_eur, whether it is total or for the tendered service.
- Never put a turnover, insurance, staff or experience amount in other_requirements: use its own field.
- "other_requirements": anything else a bidder must meet that a design practice might not already have: a professional title or chamber registration (architect, landscape architect, engineer), named qualifications or certifications, specific software or BIM formats, language, site presence, specific expertise. Each in a few plain English words (translate; never copy German or other terms into the text), max 8.
- Leave out standard paperwork every registered firm can provide: commercial or trade register extracts, tax, VAT and social security proof, insurance certificates, self-declarations or ESPD, exclusion grounds, and minimum wage, collective agreement (Tariftreue) or sanctions declarations.
- If the notice says the requirements are only in the tender documents, set requirements_in_documents_only to true.`;

const num = { anyOf: [{ type: 'number' }, { type: 'null' }] };
const str = { anyOf: [{ type: 'string' }, { type: 'null' }] };
const minimum = { type: 'object', additionalProperties: false, required: ['value', 'quote'], properties: { value: num, quote: str } };
const money = { type: 'object', additionalProperties: false, required: ['value', 'currency', 'quote'],
  properties: { value: num, currency: { type: 'string', enum: ['EUR', 'DKK', 'SEK', 'NOK', 'other'] }, quote: str } };
const TYPOLOGY = ['school', 'daycare', 'library', 'cultural', 'housing', 'student_housing', 'social_housing', 'public_space',
  'landscape', 'office', 'healthcare', 'sports', 'infrastructure', 'mixed', 'other', 'not_stated'];
const SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['building_type', 'min_annual_turnover_eur', 'min_professional_indemnity_eur', 'min_staff', 'min_lead_experience_years',
    'references', 'price_weight_percent', 'other_requirements', 'requirements_in_documents_only'],
  properties: {
    building_type: { type: 'object', additionalProperties: false, required: ['value', 'quote'],
      properties: { value: { type: 'string', enum: TYPOLOGY }, quote: str } },
    min_annual_turnover_eur: money,
    min_professional_indemnity_eur: money,
    min_staff: minimum,
    min_lead_experience_years: minimum,
    references: { type: 'object', additionalProperties: false,
      required: ['count', 'building_type', 'min_construction_cost_eur', 'construction_cost_currency', 'min_floor_area_m2', 'within_years', 'quote'],
      properties: { count: num, building_type: { type: 'string', enum: [...TYPOLOGY, 'same_as_tender', 'any'] },
        min_construction_cost_eur: num, construction_cost_currency: { type: 'string', enum: ['EUR', 'DKK', 'SEK', 'NOK', 'other'] }, min_floor_area_m2: num, within_years: num, quote: str } },
    price_weight_percent: minimum,
    other_requirements: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['text', 'quote'],
      properties: { text: { type: 'string' }, quote: { type: 'string' } } } },
    requirements_in_documents_only: { type: 'boolean' },
  },
};

// A notice TED doesn't return can't be read: it is reported as "check yourself", without a model call.
if (!Object.keys(byId).length) throw new Error(`TED returned none of the ${tenders.length} notices. Nothing was assessed; the next run tries again.`);
const noText = tenders.filter(t => !byId[t.source_id]).map(t => ({ tender_id: t.id, source_id: t.source_id }));

const out = [];
for (const t of tenders.filter(t => byId[t.source_id])) {
  const n = byId[t.source_id];
  const text = [
    section('Title', n['title-lot']),
    section('Procedure type', n['procedure-type']),
    section('Description', [n['description-proc'], n['description-lot']]),
    section('Selection criteria', [n['selection-criterion-lot'], n['selection-criterion-name-lot'], n['selection-criterion-description-lot']]),
    section('Award criteria', [n['award-criterion-type-lot'], n['award-criterion-name-lot'], n['award-criterion-description-lot'], n['award-criterion-number-weight-lot']]),
    section('Estimated value', [n['estimated-value-proc'], n['estimated-value-cur-proc']]),
  ].filter(Boolean).join('\n\n');
  out.push({ json: {
    tender_id: t.id, source_id: t.source_id, run_id, refs, facts, text, no_text: noText,
    request_body: {
      model: s.model,
      max_tokens: 16000,
      output_config: { effort: s.effort, format: { type: 'json_schema', schema: SCHEMA } },
      system: SYSTEM,
      messages: [{ role: 'user', content: `Tender notice ${t.source_id}:\n\n${text}` }],
    },
  } });
}
return out;

// Plain code, no model: check every extracted requirement against the practice's own references and facts,
// then decide GO / CONDITIONAL / CHECK YOURSELF / NO-GO, write why, and list what else the bidder must have.
const s = $('Settings').first().json;
const requests = $('Fetch notice texts from TED').all();
const responses = $input.all();                       // same order as the requests

// Which of the practice's typologies count as the same kind of project. Schools and daycares are kept apart on purpose.
const GROUP = { school: 'school', daycare: 'daycare', library: 'culture', cultural: 'culture', housing: 'housing',
  student_housing: 'housing', social_housing: 'housing', public_space: 'landscape', landscape: 'landscape' };
const NOT_PURSUED = ['healthcare', 'infrastructure'];                      // firm profile: no references, skipped
const REF_TYPE = t => String(t).toLowerCase().replace('cultural building', 'cultural').replace(/\s+/g, '_');
const FACT = { min_annual_turnover_eur: ['annual_turnover_eur', 'turnover'], min_professional_indemnity_eur: ['professional_indemnity_eur', 'insurance'],
  min_staff: ['staff', 'staff'], min_lead_experience_years: ['lead_experience_years', 'lead experience'] };
const eur = v => (v >= 1e6 ? `€${+(v / 1e6).toFixed(1)}m` : `€${Math.round(v / 1e3)}k`);
const show = (k, v) => (k.endsWith('_eur') ? eur(v) : k === 'min_lead_experience_years' ? `${v} years` : `${v}`);
const norm = t => String(t ?? '').replace(/[“”„«»]/g, '"').replace(/[‘’]/g, "'").replace(/\s+/g, ' ').trim().toLowerCase();

const rows = [];
const calls = [];
const apiDown = [];
const rejected = [];
const fail = (req, reason, usage) => {
  rows.push({ tender_id: req.tender_id, status: 'failed', status_reason: reason });
  calls.push({ tender_id: req.tender_id, run_id: req.run_id, ok: false, error: reason, ...usage });
};

requests.forEach(({ json: req }, i) => {
  const res = responses[i]?.json ?? {};
  const usage = { model: res.model ?? s.model, input_tokens: res.usage?.input_tokens ?? null, output_tokens: res.usage?.output_tokens ?? null };
  usage.cost_usd = usage.input_tokens == null ? null
    : (usage.input_tokens * s.price_in_per_mtok + usage.output_tokens * s.price_out_per_mtok) / 1e6;
  if (res.error) {
    const err = JSON.stringify(res.error).slice(0, 300);
    // Only a request the API rejects as invalid or too large is a problem with this notice: marked failed, not retried.
    // Anything else (wrong key, no credit left, rate limit, outage) is not the notice's fault: nothing is saved for it,
    // so the next run tries it again. These calls are not charged.
    if (/\b(400|413)\b|invalid_request_error|request_too_large/.test(err) && !/credit balance/i.test(err)) { rejected.push(err); return fail(req, `API call failed: ${err}`, usage); }
    apiDown.push(err);
    return calls.push({ tender_id: req.tender_id, run_id: req.run_id, ok: false, error: `API not reachable, retried next run: ${err}`, ...usage });
  }
  if (res.stop_reason !== 'end_turn') return fail(req, `Model stopped early: ${res.stop_reason}`, usage);
  const textBlock = (res.content || []).find(b => b.type === 'text');
  let x;
  try { x = JSON.parse(textBlock.text); } catch (e) { return fail(req, 'Model answer was not valid JSON', usage); }
  calls.push({ tender_id: req.tender_id, run_id: req.run_id, ok: true, error: null, ...usage });

  // No quote, no claim: a requirement whose quote is not in the notice text is dropped.
  const text = norm(req.text);
  const dropped = [];
  // A value with no quote, or with a quote that is not in the notice, is dropped and logged: it counts as not stated.
  const quoted = (field, q) => { if (q && text.includes(norm(q))) return true; dropped.push({ field, quote: q ?? null }); return false; };
  for (const k of [...Object.keys(FACT), 'price_weight_percent', 'building_type']) {
    const stated = k === 'building_type' ? (x[k]?.value && x[k].value !== 'not_stated') : x[k]?.value != null;
    if ((stated || x[k]?.quote) && !quoted(k, x[k]?.quote)) x[k] = { value: k === 'building_type' ? 'not_stated' : null, quote: null };
  }
  const refStated = x.references && (x.references.count != null || x.references.quote);
  if (refStated && !quoted('references', x.references.quote)) x.references = { count: null, quote: null };
  x.other_requirements = (x.other_requirements || []).filter(o => quoted('other_requirements', o.quote));

  const checks = [];                                    // {level: fail | partial | check | ok, text}
  // A minimum or reference requirement whose quote was not found may still be real (the model reworded it): it blocks GO.
  for (const d of dropped) {
    const label = FACT[d.field]?.[1] ?? (d.field === 'references' ? 'references' : null);
    if (label) checks.push({ level: 'check', blocking: true, text: `${label}: the model found a requirement but its quote is not in the notice; check the notice` });
  }
  const type = x.building_type?.value ?? 'not_stated';
  if (NOT_PURSUED.includes(type)) checks.push({ level: 'fail', text: `${type} is not a typology the practice pursues` });
  else if (['other', 'mixed', 'not_stated'].includes(type)) checks.push({ level: 'check', text: type === 'mixed' ? 'Mixed-use building: check if it fits the practice' : 'Building type not clear from the notice' });
  else if (!GROUP[type]) checks.push({ level: 'check', text: `${type.replace('_', ' ')} is not one of the practice's usual building types` });

  // Minimums against the practice's facts
  for (const [k, [factName, label]] of Object.entries(FACT)) {
    const r = x[k];
    if (!r?.quote || r.value == null) continue;         // not asked for, or no minimum number stated
    if (r.currency && !s.eur_per[r.currency]) { checks.push({ level: 'check', blocking: true, text: `${label}: minimum in another currency` }); continue; }
    r.value = r.value * (r.currency ? s.eur_per[r.currency] : 1);   // compared in euros
    const have = req.facts[factName];
    if (have == null) checks.push({ level: 'check', blocking: true, text: `${label}: needs ${show(k, r.value)}; practice fact missing` });
    else if (Number(have) >= r.value) checks.push({ level: 'ok', text: `${label} OK` });
    // Insurance: the notice may mean another kind of liability cover, and cover can often be raised for one contract.
    else if (factName === 'professional_indemnity_eur') checks.push({ level: 'check', blocking: true, text: `${label}: needs ${show(k, r.value)}, practice has ${show(k, Number(have))}; check the kind of cover and if it can be raised` });
    else checks.push({ level: 'fail', text: `needs ${label} ${show(k, r.value)}, practice has ${show(k, Number(have))}` });
  }

  // References: count the practice's own projects that meet every stated condition
  const ref = x.references || {};
  let refFit = null;
  if (ref.quote && !NOT_PURSUED.includes(type)) {
    const target = ref.building_type === 'same_as_tender' ? type : ref.building_type;
    // A cost limit in a currency without a rate here can't be compared: it is left out of the matching and flagged.
    let costUnknown = false;
    if (ref.min_construction_cost_eur != null) {
      const rate = s.eur_per[ref.construction_cost_currency ?? 'EUR'];
      if (rate == null) { costUnknown = true; ref.min_construction_cost_eur = null; }
      else ref.min_construction_cost_eur *= rate;
    }
    const year = new Date().getFullYear();
    // The typology is compared only when the code knows it. "Comparable" without a typology is the person's call,
    // but the cost, area and age limits are still checked: too few projects meeting them is a clear answer.
    const concrete = Boolean(GROUP[target]);
    const matched = req.refs.filter(p =>
      (!concrete || GROUP[REF_TYPE(p.typology)] === GROUP[target])
      && (ref.min_construction_cost_eur == null || Number(p.budget_eur_m) * 1e6 >= ref.min_construction_cost_eur)
      && (ref.min_floor_area_m2 == null || Number(p.size_m2) >= ref.min_floor_area_m2)
      && (ref.within_years == null || Number(p.year) >= year - ref.within_years));
    const need = ref.count;
    const what = [target && !['any', 'not_stated', 'other', 'mixed'].includes(target) ? target.replace('_', ' ') : 'comparable', 'references',
      ref.min_construction_cost_eur != null ? `over ${eur(ref.min_construction_cost_eur)}` : '',
      ref.min_floor_area_m2 != null ? `over ${ref.min_floor_area_m2} m²` : '',
      ref.within_years != null ? `from the last ${ref.within_years} years` : ''].filter(Boolean).join(' ');
    const ids = matched.length && matched.length === req.refs.length ? `any of the ${matched.length} reference projects` : matched.map(p => p.id).join(', ');
    refFit = { required: need, conditions: { building_type: target, min_construction_cost_eur: ref.min_construction_cost_eur,
      min_floor_area_m2: ref.min_floor_area_m2, within_years: ref.within_years }, matched: matched.map(p => p.id) };
    const plural = n => (n === 1 ? what.replace(' references', ' reference') : what);
    if (!concrete && (need == null || matched.length >= need)) {
      // Enough projects meet the limits, but whether they count is a judgment: it blocks GO.
      checks.push({ level: 'check', blocking: true, text: `${need ?? 'Some'} ${need === 1 ? plural(1) : what} asked for: decide which count${ids ? ` (could be ${ids})` : ''}` });
    } else if (need == null) checks.push({ level: 'check', blocking: true, text: `${what} asked for, number not stated${ids ? ` (matching: ${ids})` : ''}` });
    else if (matched.length >= need) checks.push({ level: 'ok', refs: true, text: `${need} ${plural(need)} OK (${ids})` });
    else if (matched.length > 0) checks.push({ level: 'partial', text: `needs ${need} ${plural(need)}, practice has ${matched.length} (${ids})` });
    else checks.push({ level: 'fail', text: `needs ${need} ${plural(need)}, practice has none` });
    if (costUnknown) checks.push({ level: 'check', blocking: true, text: 'Reference construction cost given in another currency: check which projects are large enough' });
  }

  // Safety net: a requirement left to check that names an amount (money or a number with a unit) is probably a minimum
  // the model did not put in its own field. It can't be compared here, so it blocks GO.
  const AMOUNT = /(€|\beur\b|\beuro\b|\bmio\b|million|\bkr\b|\bnok\b|\bsek\b|\bdkk\b)/i;
  for (const o of x.other_requirements) {
    const blocking = AMOUNT.test(o.text) || AMOUNT.test(o.quote);
    checks.push({ level: 'check', other: true, blocking, text: blocking ? `${o.text} (amount not compared)` : o.text });
  }

  const has = l => checks.some(c => c.level === l);
  const compared = checks.some(c => ['ok', 'partial', 'fail'].includes(c.level));
  // A clear shortfall is NO-GO. An unclear or unusual building type, or anything left open that blocks GO, is the person's call.
  // GO only for a typology the practice pursues, with every comparable minimum met and nothing with an amount left open.
  const recommendation = has('fail') ? 'no_go'
    : (!GROUP[type] || !compared || checks.some(c => c.blocking)) ? 'unresolved'
    : has('partial') ? 'conditional_go' : 'go';

  const order = { fail: 0, partial: 1, ok: 2, check: 3 };
  const sorted = [...checks].sort((a, b) => order[a.level] - order[b.level]);
  // Why, short enough to read in one cell: what decides it, then at most 2 things to check.
  const okLabels = sorted.filter(c => c.level === 'ok' && !c.refs).map(c => c.text.replace(/ OK$/, ''));
  const main = [
    ...sorted.filter(c => c.level === 'fail' || c.level === 'partial').map(c => c.text),
    ...sorted.filter(c => c.level === 'ok' && c.refs).map(c => c.text),
    ...(okLabels.length ? [`${okLabels.join(', ')} OK`] : []),
  ];
  // Why: only what decides the verdict, in full. Everything else the bidder must have goes to "Also required".
  const decides = sorted.filter(c => c.level === 'check' && (c.blocking || !c.other)).map(c => c.text);
  const also = checks.filter(c => c.other && !c.blocking).map(c => c.text);
  const cap = t => t.charAt(0).toUpperCase() + t.slice(1);
  let why = main.map(cap).join('. ');
  if (!compared) why = x.requirements_in_documents_only ? 'Requirements are only in the tender documents' : 'Nothing in the notice the code can compare';
  // How much of the award score is price: high means the cheapest bid tends to win, low means quality decides.
  const pw = x.price_weight_percent?.value;
  if (pw != null) why += `${why ? '. ' : ''}${pw >= 100 ? 'Lowest price wins (price is 100% of the score)' : `Price is ${pw}% of the score`}`;
  if (decides.length) why += `${why ? '. ' : ''}To decide: ${decides.map(cap).join('; ')}`;

  rows.push({ tender_id: req.tender_id, status: 'new', status_reason: null, recommendation, explanation: why,
    open_questions: also, requirements: { ...x, dropped_without_quote: dropped, rules_version: s.rules_version }, reference_fit: refFit });
});

// Notices TED did not return: nothing to read, so the person checks them.
for (const t of requests[0]?.json.no_text ?? []) {
  rows.push({ tender_id: t.tender_id, status: 'new', status_reason: null, recommendation: 'unresolved',
    // requirements stays empty, so the next run asks TED again (free, no model call).
    explanation: 'TED returned no requirement text for this notice', open_questions: [], requirements: null, reference_fit: null });
}
// If no call got through at all, stop the run so the error shows in n8n. Nothing was saved, nothing was charged.
// If the API rejected every request, the request itself is wrong (e.g. a setting), not the notices: stop, mark nothing failed.
if (rejected.length && rejected.length === requests.length) throw new Error(`Anthropic API rejected every request, so nothing was saved. Check the model and settings in the Settings step: ${rejected[0]}`);
if (apiDown.length && apiDown.length === requests.length) throw new Error(`Anthropic API not reachable, check the API key credential and credit: ${apiDown[0]}`);
return [{ json: { rows, calls } }];
